				<div class="elementor-widget-container">
									<p>Mọi người hay gọi vùng đất Đồng Bằng Sông Cửu Long ở Việt Nam với cái tên mộc mạc là miền Tây. Và người ta gọi thủ phủ của nó, thành phố Cần Thơ là Tây Đô.</p><p>Cần Thơ, vùng đất đô thị trẻ trung năng động với nhiều dịch vụ du lịch thú vị. Nhưng cũng không kém phần mộc mạc, sông nước với những cảnh mang dấu ấn sông nước miền Tây.</p>								</div>
