INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (5726, 'Resort Lagoon Project', 'resort-lagoon-project', '		<div data-elementor-type="wp-post" data-elementor-id="5726" class="elementor elementor-5726" data-elementor-post-type="post">
						<section class="elementor-section elementor-top-section elementor-element elementor-element-d31738d elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="d31738d" data-element_type="section" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
						<div class="elementor-container elementor-column-gap-default">
					<div class="elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-bc8c14f" data-id="bc8c14f" data-element_type="column">
