				<div class="elementor-widget-container">
									<p>Dự án mang đến thiết kế về phòng resort với guu ở riêng biệt. Phòng ở được thể hiện đầy đủ và tinh tế với phòng ở, dịch vụ và mang đến thông điệp riêng dành cho khách hàng.</p><p>Một thiết kế tuỳ chỉnh, đơn giản và khả năng thay đổi dễ dàng.</p>								</div>
