INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (5701, 'Thiết kế Website &#038; Kế hoạch Nội dung cho DuLichCoGuu (Fit Tour)', 'dulichcoguu', '		<div data-elementor-type="wp-post" data-elementor-id="5701" class="elementor elementor-5701" data-elementor-post-type="post">
						<section class="elementor-section elementor-top-section elementor-element elementor-element-5b1f78c elementor-section-boxed elementor-section-height-default elementor-section-height-default" data-id="5b1f78c" data-element_type="section" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
						<div class="elementor-container elementor-column-gap-default">
					<div class="elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-997863c" data-id="997863c" data-element_type="column">
			<div class="elementor-widget-wrap elementor-element-populated">
						<div class="elementor-element elementor-element-c2b6ae2 elementor-widget elementor-widget-text-editor" data-id="c2b6ae2" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Case Study</p>								</div>
				</div>
				<div class="elementor-element elementor-element-93c9081 elementor-widget elementor-widget-jet-listing-dynamic-field" data-id="93c9081" data-element_type="widget" data-widget_type="jet-listing-dynamic-field.default">
				<div class="elementor-widget-container">
					<div class="jet-listing jet-listing-dynamic-field display-inline"><div class="jet-listing-dynamic-field__inline-wrap"><h1 class="jet-listing-dynamic-field__content">Ý nghĩa lá bài X of Wands trong Tarot</h1></div></div>				</div>
				</div>
				<div class="elementor-element elementor-element-46617d8 elementor-widget elementor-widget-text-editor" data-id="46617d8" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Vai trò của tôi</p>								</div>
				</div>
				<div class="elementor-element elementor-element-6e10b24 elementor-widget elementor-widget-text-editor" data-id="6e10b24" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Thiết kế Website</p><p>Kế hoạch chiến lược Nội dung</p><p>Đánh giá và đăng tải Nội dung</p>								</div>
				</div>
				<div class="elementor-element elementor-element-5d22ec9 elementor-widget elementor-widget-text-editor" data-id="5d22ec9" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Client</p>								</div>
				</div>
				<div class="elementor-element elementor-element-08a01d8 elementor-widget elementor-widget-text-editor" data-id="08a01d8" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Fit Tour</p>								</div>
				</div>
				<div class="elementor-element elementor-element-bdcf3d3 elementor-widget elementor-widget-text-editor" data-id="bdcf3d3" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Thời Gian</p>								</div>
				</div>
				<div class="elementor-element elementor-element-83684f8 elementor-widget elementor-widget-text-editor" data-id="83684f8" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>2021 &#8211; nay</p>								</div>
				</div>
					</div>
		</div>
				<div class="elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-74c5903" data-id="74c5903" data-element_type="column">
			<div class="elementor-widget-wrap elementor-element-populated">
						<div class="elementor-element elementor-element-2be773d elementor-widget elementor-widget-text-editor" data-id="2be773d" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Fit Tour &#8211; Du lịch có Guu là công ty với nhiều sản phẩm &#8220;Độc, Lạ và có Guu&#8221; trong ngành du lịch Việt Nam. Một trong những yêu cầu đầu tiên khi thực hiện website là thể hiện được chất riêng của Doanh nghiệp lên website.</p><p>Tôi rất vui rằng ưu thế sự đa dạng trong Thiết kế được nhiều Landing Page của mình trở thành đặc tính kết hợp tuyệt vời cho cả hai. Một số ý tưởng ban đầu triển khai và thật sự mang đến thành công ngay lập tức khi thực hiện. Tôi cũng bắt đầu phác thảo nhiều kế hoạch hơn khi bắt đầu dự án.</p><p>Mục tiêu của tôi là có thể khai thác được thiết kế Emagazine, một dạng Tạp chí Online với hình ảnh đồ hoạ &amp; nội dung hình ảnh nổi bật. Việc mang đến cảm hứng và thể hiện được rõ nét các chuyến đi và thực hiện nội dung mang thương hiệu Du lịch có Guu được ưu tiên hàng đầu.</p><p>Sản phẩm hiện tại vẫn đang hoàn thiện hơn. Điều may mắn là một dự án với sự tin tưởng và hợp tác gần như toàn vẹn từ Doanh nghiệp đối tác (Từ việc chuẩn bị hình ảnh, nội dung bài viết) mang đến khả năng hình thành vô cùng tốt cho các bài viết.</p><p>Chúng tôi gặt hái được tốt nhất từ Trải nghiệm thật sự có Guu từ ngay trang Web riêng. Thương hiệu được thể hiện đúng ngay từ ban đầu (Thay vì phải kết nối qua các buổi gặp mặt hay trải nghiệm sản phẩm thật sự)..</p>								</div>
				</div>
				<div class="elementor-element elementor-element-f5c584c elementor-position-left elementor-mobile-position-right elementor-view-default elementor-widget elementor-widget-icon-box" data-id="f5c584c" data-element_type="widget" data-widget_type="icon-box.default">
				<div class="elementor-widget-container">
							<div class="elementor-icon-box-wrapper">

						<div class="elementor-icon-box-icon">
				<span  class="elementor-icon">
				<i aria-hidden="true" class="fas fa-chevron-right"></i>				</span>
			</div>
			
						<div class="elementor-icon-box-content">

									<div class="elementor-icon-box-title">
						<span  >
							Xem Thêm Dự Án Chính Thức						</span>
					</div>
				
				
			</div>
			
		</div>
						</div>
				</div>
