INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (5453, 'Top 20 Quán Cafe Yên Tĩnh Cần Thơ Học Bài Và Làm Việc', 'quan-cafe-yen-tinh-can-tho', '
<p>Những ngày học bài hay làm việc luôn cần những không gian yên tĩnh. Những quán cafe yên tĩnh Cần Thơ với không gian đẹp, những món nước ngon này là dành cho bạn. Cùng mình khám phá những quán cà phê <a href="https://huynhhieutravel.com/dia-diem-du-lich/can-tho/" target="_blank" rel="noreferrer noopener">Cần Thơ</a> này ngay nhé!</p>



<h2 class="wp-block-heading">Highlands Coffee</h2>



<p><strong>Địa chỉ 1</strong>: Highlands Coffee Vincom Cần Thơ, 2 Hùng Vương, Quận Ninh Kiều, Cần Thơ</p>



<p><strong>Địa chỉ 2</strong>: Highlands Coffee Lotte Mart, 84 Mậu Thân, P. An Hòa, Quận Ninh Kiều, Cần Thơ</p>



<p><strong>Địa chỉ 3</strong>: Highlands Coffee Vincom Xuân Khánh, 54A8 Đường 30 Tháng 4, Xuân Khánh, Ninh Kiều, Cần Thơ</p>



<p><strong>Địa chỉ 4</strong>: Highlands Coffee 3- 2 Số1, đường 3/2, phường Xuân Khánh, quận Ninh Kiều, Tp. Cần Thơ</p>



<p><strong>Địa chỉ 5</strong>: Highlands Coffee Sense City 36 Đại lộ Hòa Bình, phường Tân An, quận Ninh Kiều, Tp. Cần Thơ</p>



<h2 class="wp-block-heading">Hoa Yên</h2>



<p><strong>Đia chỉ</strong>: 131 Lý Tự Trọng, P. An Phú, Quận Ninh Kiều, Thành phố Cần Thơ.</p>



<figure class="wp-block-image size-large"><img decoding="async" src="https://mientaycogi.com/wp-content/uploads/2020/10/workshop-duoc-to-chuc-ben-trong-hoa-yen-ca-phe-1068x610.jpg" alt=""/></figure>



<h2 class="wp-block-heading">1985 cafe</h2>



<p>Địa chỉ: 138 Huỳnh Cương, P. An Cư, Quận Ninh Kiều, Cần Thơ</p>



