<h2 class="wp-block-heading">Vitamin Plus hồ Bún Xáng</h2>



<p><strong>Đia chỉ</strong>: Hẻm 51, Xuân Khánh, Ninh Kiều, Cần Thơ.</p>



<figure class="wp-block-image size-large"><img decoding="async" src="https://mientaycogi.com/wp-content/uploads/2020/09/khong-gian-tang-2-quan-vitamin-can-tho.jpg" alt=""/></figure>



